// Native selected original officers only. Cancel presentation/engine wait, never persistence.
export async function waitCargoOfficerBattle(play,signal){if(!(signal instanceof AbortSignal))throw Error('INVALID_CARGO_OFFICER_LIFECYCLE');const cancelled=()=>Object.assign(Error('CARGO_OFFICER_DISPOSED'),{code:'CARGO_OFFICER_DISPOSED'});if(signal.aborted)throw cancelled();let cancel;try{return await new Promise((resolve,reject)=>{cancel=()=>reject(cancelled());signal.addEventListener('abort',cancel,{once:true});Promise.resolve().then(()=>{if(signal.aborted)throw cancelled();return play()}).then(resolve,reject)})}finally{signal.removeEventListener('abort',cancel)}}
